-- 시우스 책 서재 — 읽기 안내 칸 추가 + 24권 내용 (2026-11-11, 제작팀·기록팀)
-- 서치콘솔 「크롤링됨-현재 색인 안 됨」 대응. 등록자 후기(note·rating)는 건드리지 않는다.
-- 여러 번 실행해도 결과가 같다(칸은 if not exists, 내용은 id로 덮어쓰기).

alter table public.syus_books add column if not exists reader_reception text;
alter table public.syus_books add column if not exists reader_sources jsonb not null default '[]'::jsonb;
alter table public.syus_books add column if not exists actor_guide text;
alter table public.syus_books add column if not exists read_level smallint;
alter table public.syus_books add column if not exists for_whom text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'syus_books_read_level_range') then
    alter table public.syus_books add constraint syus_books_read_level_range check (read_level is null or read_level between 1 and 3);
  end if;
end $$;

begin;
-- 액팅 원 (Acting One)
update public.syus_books set
  reader_reception = $q$미국에서 1984년 초판이 나온 뒤 판을 거듭하며 대학 연기 수업의 교재로 쓰여 온 책이다. 미국 출판사는 대학에서 연기를 가르치는 데 가장 널리 쓰인 교재라고 소개하고, 지금은 후속작 《Acting Two》와 한 권으로 묶어 낸다. 영미권 독자들은 혼자서도 해 볼 수 있는 연습이 많다는 점과, 목표·상대·전술·기대를 하나로 묶은 GOTE라는 틀이 다른 책보다 또렷하다는 점을 주로 꼽는다. 반면 인물을 만들어 가는 성격화는 거의 다루지 않는다는 지적과, 수업에 쓰기엔 연습이 더 있었으면 한다는 평도 있다. 국내판(경당, 2012 개정증보판)은 원서 5판(2008)을 옮긴 것으로, 서점 독자평은 열 건 남짓이고 대체로 좋은 평가를 받는다.$q$,
  reader_sources = $q$[{"name": "McGraw Hill 책 소개", "url": "https://www.mheducation.com/highered/product/Acting-One-Cohen.html"}, {"name": "Goodreads", "url": "https://www.goodreads.com/book/show/922299"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/6414174"}, {"name": "알라딘", "url": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=15681735"}]$q$::jsonb,
  actor_guide = $q$연기 수업 첫 학기 교과서로 짜인 책이라, 연극영화과 1학년이나 입시 준비를 막 시작한 사람이 처음 펴기 좋다. 2부(배우의 접근법)의 목표와 장애물, 다른 사람과의 연기, 전술, 기대, GOTE로 이어지는 장들이 이 책의 뼈대이니 여기부터 읽고, 읽은 장의 연습을 짧은 장면에 직접 해 보는 편이 낫다. 입시 독백을 준비할 때는 마지막 장인 독백의 창조를 읽은 뒤, 목표와 상대라는 틀로 자기 독백 대본을 다시 읽어 보면 바로 쓸 수 있다. 4부의 음성·화술 장은 원서의 영어 발음을 전제로 한 부분이 있어 역자도 지도자의 조정이 필요하다고 밝히니, 한국어 화술은 같은 서재의 《배우를 위한 화술과 연기》로 보충하길 권한다. 기초가 잡히면 《산연기》로 넘어가 같은 질문을 다른 선생의 말로 들어 보는 것도 좋다.$q$,
  read_level = 1,
  for_whom = $q$연기를 처음 체계적으로 배우는 사람, 입시 독백을 준비하는 사람$q$
where id = 'b2399014-f9ed-4689-9ac5-180ac1b8b328';

-- 빈 공간 (The Empty Space)
update public.syus_books set
  reader_reception = $q$1968년에 나온 뒤 연극을 공부하는 사람의 필독서로 자리 잡은 책이다. 영국의 연극학자들은 지금도 현대 연극에 가장 큰 영향을 준 책 가운데 하나로 꼽는다. 가장 자주 인용되는 대목은 첫머리의 생각 — 빈 공간을 누군가 가로지르고 다른 누군가가 그것을 지켜보면 그것으로 연극이 시작된다는 것이다. 습관과 관습만 남아 생기를 잃은 공연을 죽은 연극이라 부르며 몰아세우는 1장이 특히 날카롭다는 평이 많다. 아쉬운 점으로는 남성 대명사 중심의 서술처럼 1960년대 글의 흔적이 지적된다. 국내판(2019, 걷는책) 독자평은 많지 않다.$q$,
  reader_sources = $q$[{"name": "The Conversation", "url": "https://theconversation.com/an-ever-innovative-director-peter-brook-reminded-us-how-high-the-stakes-of-theatre-can-be-186290"}, {"name": "예스24", "url": "https://www.yes24.com/Product/goods/76893459"}, {"name": "교보문고", "url": "https://product.kyobobook.co.kr/detail/S000001535371"}]$q$::jsonb,
  actor_guide = $q$연기하는 방법이 아니라 왜 무대에 서는가를 묻는 책이다. 강연을 옮긴 글이라 문장 자체는 어렵지 않지만, 예로 드는 연극인들(아르토, 그로토프스키, 브레히트 등)을 모르면 중간에 막힐 수 있다. 처음에는 1장(죽은 연극)과 4장(살아 있는 연극)을 먼저 읽고, 연극사를 배운 뒤 2·3장을 다시 읽으면 훨씬 잘 들어온다. 입시 면접에서 좋은 연극이란 무엇이라고 생각하는가 같은 질문을 받았을 때 자기 말로 답할 재료가 된다.$q$,
  read_level = 2,
  for_whom = $q$연극 전공 1~2학년, 연기·연출 면접을 준비하는 사람$q$
where id = 'a5a30e2d-b05b-46c0-8801-ceed3ccf61a4';

-- 배우를 위한 화술과 연기
update public.syus_books set
  reader_reception = $q$연극과인간에서 2007년에 처음 나온 국내 저자의 화술 교재다. 온라인 서점의 독자 서평은 거의 찾을 수 없지만, 대학 부설 교육기관의 화술 과목에서 주교재로 쓰인다는 점이 이 책의 자리를 보여 준다. 한성대 콘텐츠디자인칼리지의 화술Ⅰ과 국민대 미래인재교육원의 화술Ⅱ 수업계획서가 모두 이 책을 주교재로 적고 있고, 주차별 진도도 책의 장 순서를 거의 그대로 따른다. 호흡·발성·공명에서 출발해 우리말의 소리마루와 억양, 끊어 말하기, 장단음으로 나아가는 구성이 한 학기 수업의 뼈대로 쓰이는 셈이다. 다만 서점에 따라 새 책이 품절로 표시되어 있어, 도서관이나 중고로 구해야 할 수 있다.$q$,
  reader_sources = $q$[{"name": "한성대 화술Ⅰ 수업계획서", "url": "https://hansung.ac.kr/sites/edubank/contents/files/000002/%ED%99%94%EC%88%A0%E2%85%A0.pdf"}, {"name": "국민대 미래인재교육원 화술Ⅱ 수업계획서", "url": "https://lifelong.kookmin.ac.kr/common/pdf/%ED%99%94%EC%88%A0%E2%85%A1.pdf"}, {"name": "예스24(목차)", "url": "https://www.yes24.com/product/goods/2640734"}]$q$::jsonb,
  actor_guide = $q$화술 수업을 앞둔 연기과 신입생이나, 입시 독백을 소리 내어 다듬는 단계에서 곁에 두기 좋은 책이다. 먼저 2장(화술 전 단계훈련)의 호흡·발성·공명 훈련으로 몸을 열고, 이어서 3장(우리말의 일반적 법칙)에서 소리마루(말의 높이·길이·세기가 솟는 자리)와 억양, 끊기와 사이를 익히면 내 대사가 왜 읽는 소리처럼 들리는지 스스로 짚을 수 있다. 4장(화술의 실제)은 대본을 처음 읽을 때와 발음 훈련 과정에서 흔히 생기는 문제를 다루므로, 입시 독백을 녹음해 들으며 하나씩 대조해 보기 좋다. 면접에서 발음이나 사투리 교정을 어떻게 해 왔는지 물을 때도 이 책의 용어로 자기 훈련을 설명할 수 있다. 호흡과 소리 훈련을 더 깊이 하고 싶다면 같은 서재의 《음성연기를 위한 호흡·소리 훈련》을 함께 보길 권한다 — 두 책은 실제로 한 수업에서 주교재와 부교재로 짝지어 쓰이기도 한다.$q$,
  read_level = 2,
  for_whom = $q$화술 수업을 앞둔 연기과 신입생, 입시 독백의 말투가 고민인 사람$q$
where id = '697d17ad-b06a-4877-bde0-bb71d1ca716b';

-- 배우 수업
update public.syus_books set
  reader_reception = $q$1936년 미국에서 영어판 《An Actor Prepares》로 먼저 나온 뒤, 무대와 화면 연기 교육 전반에 영향을 준 책이다. 연기 학교 1학년 학생 코스챠가 선생 토르초프에게 배운 것을 일기로 적어 가는 소설 형식이라, 목록식 교재보다 잘 읽힌다는 독자가 있는 반면 이야기 틀이 어색하고 길게 늘어진다는 반응도 있다. 영미권에서는 이 영어판이 러시아어 원문을 크게 줄이고 핵심 용어를 오해를 부르는 말로 옮겼다는 비판이 오래 이어졌고, 2008년 진 베네데티가 원문에 가깝게 다시 옮긴 《An Actor's Work》가 나왔다. 국내판(예니, 신겸수 옮김)도 목차에 영문판 번역자 해설이 실려 있어 영어판을 거친 번역으로 보이며, 국내 연구에서도 스타니슬랍스키 초기 저작 번역이 대부분 영어나 일본어를 거쳐 용어가 흔들렸다는 지적이 있다. 국내판은 2001년 이후 판을 바꿔 가며 꾸준히 읽혀 서점 독자평이 스무 건 남짓 쌓였고, 평가는 대체로 좋다.$q$,
  reader_sources = $q$[{"name": "Wikipedia(An Actor Prepares)", "url": "https://en.wikipedia.org/wiki/An_Actor_Prepares"}, {"name": "Times Higher Education 서평", "url": "https://www.timeshighereducation.com/node/82396"}, {"name": "Scene4 Magazine", "url": "https://www.scene4.com/archivesqv6/mar-2008/html/nathanthomas0308.html"}, {"name": "한국연극학(김대현, 2010)", "url": "https://koreascience.kr/article/JAKO201035353133065.page?lang=ko"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/12185003"}]$q$::jsonb,
  actor_guide = $q$국내 연극영화과 수업에서 자주 거론되는 연기 이론서라, 전공을 준비한다면 한 번은 직접 읽어 두는 것이 좋다. 열여섯 장이 행동, 상상력, 주의 집중, 근육 이완, 단위와 목표, 믿음과 진실감, 정서 기억, 교감, 초목표 순으로 이어지는데, 처음에는 1~2장으로 소설의 결을 익힌 뒤 4장(상상력)과 7장(단위와 목표), 15장(초목표)을 먼저 읽으면 뼈대가 잡힌다. 면접에서 스타니슬랍스키나 초목표를 묻는다면 용어를 외워 말하기보다 자기 독백에 적용해 본 경험으로 답하는 편이 낫다. 9장(정서 기억)은 뒤에 여러 갈래로 해석이 갈린 대목이라, 같은 서재의 《아메리칸 액팅 메소드의 이해》나 《배우훈련》 1장과 함께 읽으면 왜 논쟁이 되었는지 보인다. 번역어가 판본과 수업마다 조금씩 다르니, 수업에서 쓰는 용어와 대조하며 읽는 것이 좋다.$q$,
  read_level = 2,
  for_whom = $q$연기 이론을 처음 공부하는 전공생, 면접에서 연기론 질문을 대비하는 입시생$q$
where id = '3eaf7ce7-0c64-4581-9705-2ad1db8e6615';

-- 스스로 빛나는 배우를 찾습니다
update public.syus_books set
  reader_reception = $q$2015년, CJ E&M 캐스팅팀에서 일하던 두 저자가 펴낸 책이다. 서점에 남은 독자평은 열 건 남짓으로 많지 않다. 남은 평들은 대체로 연기 기술보다 배우의 마음가짐과 태도를 다룬 점, 현장 사람들의 조언이 솔직하고 현실적이라는 점을 좋게 본다. 배우를 꿈꾸는 친구나 자녀에게 주려고 샀다는 평, 고등학생이 진로를 정하는 데 도움을 받았다는 평이 눈에 띄고, 성실과 겸손 같은 이야기가 다른 직업을 준비하는 사람에게도 통한다는 반응도 있다. 반면 한 번 읽고 나니 다시 펼 일이 없었다는 낮은 평도 하나 있다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개·독자평", "url": "https://www.yes24.com/product/goods/17725334"}, {"name": "알라딘 100자평", "url": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=58451076"}]$q$::jsonb,
  actor_guide = $q$연기 교재가 아니라, 배우를 고르는 쪽에서 본 업계 안내서다. 프로필, 오디션, 소속사 고르기, SNS와 노출처럼 학교나 학원에서 잘 다루지 않는 현실적인 판단을 다루므로, 입시를 마치고 매체 오디션을 처음 준비할 때 읽으면 쓸모가 크다. 오디션을 다룬 장과 신인 배우에게 권하는 열 가지를 먼저 읽고, 소속사와 매니저 이야기는 실제로 제안을 받기 전에 한 번 더 읽어 두면 좋다. 류승룡, 조진웅, 나영석, 신원호 등 배우·감독·PD 열한 명의 조언도 함께 실렸다. 다만 2015년에 나온 책이라 SNS나 매체 환경에 관한 부분은 지금 사정과 다를 수 있으니 판단의 틀로만 가져가고, 카메라 앞 연기 자체는 같은 서재의 《굿캐스팅》 같은 실기서로 따로 채우는 편이 좋다.$q$,
  read_level = 1,
  for_whom = $q$매체 오디션을 처음 준비하는 사람, 소속사 계약이 궁금한 사람$q$
where id = '19d934d1-da7a-480d-9a3c-148aa6b4275d';

-- 배우의 방
update public.syus_books set
  reader_reception = $q$영화 기자 정시우가 씨네플레이에 연재하던 인터뷰를 묶고, 인터뷰마다 저자의 글을 덧붙인 책이다. 독자들이 가장 많이 꼽는 점은 작품 홍보를 위한 인터뷰가 아니라 배우가 고른 일상의 공간에서 나눈 대화라, 작품 밖의 사람이 보인다는 것이다. 가족이 하는 식당, 단골 가게, 호숫가 산책길처럼 장소가 바뀔 때마다 대화의 결도 달라진다는 평이 있고, 스태프 없이 휴대폰으로 찍은 사진이 현장감을 더한다는 반응도 있다. 배우마다 불안이나 열등감을 어떻게 다뤄 왔는지에 관한 대목이 오래 남는다는 독자가 많다. 반면 인터뷰마다 흥미의 편차가 있어 몇 편은 지루했다는 평도 있다.$q$,
  reader_sources = $q$[{"name": "엘르 코리아", "url": "https://www.elle.co.kr/article/66932"}, {"name": "예스24 독자평", "url": "https://www.yes24.com/product/goods/108736825"}]$q$::jsonb,
  actor_guide = $q$연기 방법을 가르치는 책이 아니라, 배우 열 명이 연기와 삶을 어떻게 붙들고 있는지를 듣는 인터뷰집이다. 박정민부터 고두심까지 경력의 길이가 서로 다른 배우들이 함께 실려 있어, 막 이름이 알려지기 시작한 시기의 고민과 오래 일한 사람의 태도를 한 권에서 견주어 볼 수 있다. 처음부터 순서대로 읽기보다 관심 가는 배우의 장을 먼저 읽고, 그 배우의 작품을 한 편 다시 본 뒤 나머지를 읽으면 대화가 더 잘 들어온다. 면접에서 닮고 싶은 배우를 물었을 때 이름만이 아니라 그 사람이 일을 대하는 태도로 답할 재료가 된다. 연기만 묻는 대화를 더 깊이 읽고 싶다면 같은 서재의 《배우와 배우가》를, 이름이 덜 알려진 배우들의 이야기는 《신스틸러에게 묻다》를 이어 읽어 볼 만하다.$q$,
  read_level = 1,
  for_whom = $q$연기 책이 처음인 사람, 좋아하는 배우의 생각이 궁금한 사람$q$
where id = '6f83a689-5b45-48d5-9659-9d5d92bb2ca1';

-- 배우처럼 액트아웃
update public.syus_books set
  reader_reception = $q$액팅디렉터 이윤정이 2019년에 펴낸 책으로, 지금은 절판되어 중고로만 구할 수 있다. 서점에 남은 독자평은 거의 찾을 수 없어, 반응의 경향을 말하기는 어렵다. 출판사 소개는 배우의 역할 훈련을 면접·발표·협상 같은 일상의 결정적인 순간으로 옮겨 쓴다는 점, 코치 없이 혼자 따라 할 수 있는 연습(자기 분석 질문, 얼굴 스트레칭, 목소리 찾기, 감성 일기 등)을 담았다는 점을 앞세운다. 정신건강의학과 교수, 드라마 작가, 배우 등이 추천평을 보탰다. 독자의 검증이 아직 쌓이지 않은 책이라는 점을 감안하고 펴는 편이 좋다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개", "url": "https://www.yes24.com/product/goods/68794666"}, {"name": "알라딘 책 정보", "url": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=178909074"}]$q$::jsonb,
  actor_guide = $q$배우가 되려는 사람을 위한 연기 교재가 아니라, 연기 훈련법을 일반인의 자기표현에 옮겨 온 책이다. 그래서 장면 연기나 대본 분석을 익히려는 입시생에게는 맞지 않는다. 대신 면접장에서 긴장으로 표정과 목소리가 굳는 편이라면, 뒷부분의 자기 객관화·자기 활성화 단계(얼굴 스트레칭, 목소리 찾기, 감성 일기)를 면접 전 몸풀기로 빌려 쓸 수 있다. 감각·감정·감성을 나누어 보는 앞부분은 내 감정을 말로 정리하는 연습으로 읽어도 된다. 연기의 기초는 같은 서재의 《산연기》나 《액팅 원》 같은 교본에서 따로 다지길 권한다.$q$,
  read_level = 1,
  for_whom = $q$면접에서 긴장으로 굳는 사람, 자기표현이 서툰 사람$q$
where id = 'ccf333d0-265f-4e09-a34f-435591392e47';

-- 배우와 배우가
update public.syus_books set
  reader_reception = $q$김신록이 웹진 《연극in》에 2019년부터 2021년까지 연재한 「배우가 만난 배우」 시리즈를 바탕으로, 같은 배우들을 팬데믹 이후 다시 만나 두 번의 대화를 나란히 실은 책이다. 독자들이 가장 많이 꼽는 점은 사생활 대신 연기만을 묻는 대화의 밀도, 그리고 시간 차를 둔 두 번의 인터뷰에서 배우들의 생각이 변해 가는 모습이다. 연기 이야기가 결국 일과 삶을 대하는 태도로 이어져, 연기를 하지 않는 독자도 자기 일을 돌아보게 되었다는 반응이 많고, 읽고 나서 대학로 연극을 보고 싶어졌다는 평도 눈에 띈다. 반대로 가벼운 배우 에세이를 기대하고 펴면 전문적이고 지루하게 느껴진다는 평이 있고, 초반 몇 편은 배경지식을 찾아 가며 읽어야 했다는 독자도 있다. 저자는 이 책이 형식은 인터뷰집이지만 스스로에게는 연기 이론서이자 실천서라고 소개했다.$q$,
  reader_sources = $q$[{"name": "예스24 독자 리뷰", "url": "https://www.yes24.com/product/goods/116999647"}, {"name": "하퍼스 바자 인터뷰", "url": "https://harpersbazaar.co.kr/article/74472"}, {"name": "레이디경향", "url": "https://lady.khan.co.kr/issue/article/202301301752001"}]$q$::jsonb,
  actor_guide = $q$연기를 배우기 시작했지만 연기란 무엇인가에 대한 자기 말이 아직 없는 사람에게 권할 만하다. 처음부터 순서대로 읽기보다, 무대에서 본 적 있거나 이름을 아는 배우의 장을 먼저 펴 보는 편이 덜 지친다. 배우마다 몸 훈련, 생계, 지방 공연, 당사자성처럼 서로 다른 길로 연기에 다가가므로, 읽으면서 나라면 어떻게 답할지를 노트에 적어 두면 입시 면접의 연기관 질문에 쓸 재료가 된다. 장마다 두 번의 대화 사이에 무엇이 바뀌었는지 견주어 읽는 것도 이 책을 잘 쓰는 방법이다. 비슷한 결의 인터뷰집으로는 같은 서재의 《배우의 방》과 《신스틸러에게 묻다》가 있고, 여기서 오간 연기론의 뿌리를 따라가고 싶다면 《배우훈련》이 다음 책이 된다.$q$,
  read_level = 2,
  for_whom = $q$자기 연기관을 세우고 싶은 연극과 학생, 면접에서 연기론을 말해야 하는 입시생$q$
where id = '5817bb09-013a-4001-9f22-ea8c99c17fb8';

-- 배우라는 세계
update public.syus_books set
  reader_reception = $q$30년 동안 배우를 가르쳐 온 연기 코치 신용욱의 첫 에세이로, 2024년 가을에 나왔다. 독자평은 대체로 호의적이며, 배우가 기다리고 준비하는 시간을 다룬 이야기가 연기 밖의 일과 삶에도 그대로 통한다는 반응이 가장 많다. 문장이 담백하고 읽기 편하다는 평, 저자가 가르친 배우들의 일화를 읽고 나니 그들이 연기한 인물이 달리 보이더라는 평이 이어진다. 연기를 꿈꾸는 사람이라면 여러 번 되풀이해 읽을 책이라는 한줄평도 있다. 다만 평의 상당수가 출간 직후 며칠 사이에 올라온 것이라, 시간이 지난 뒤의 반응은 아직 많지 않고 뚜렷한 아쉬움을 적은 평도 찾지 못했다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개·독자평", "url": "https://www.yes24.com/product/goods/133217357"}]$q$::jsonb,
  actor_guide = $q$연기 방법론을 정리한 교재가 아니라, 연기를 대하는 태도에 관한 에세이다. 인내·발견·배움·채움의 네 부가 배우가 자라는 순서를 따르고 있어, 입시를 앞두고 있거나 공백기를 지나는 사람이라면 기다림과 재능을 다룬 1부부터, 연습이 막혀 있다면 나라는 악기와 질투, 불안을 다룬 2부부터 펴 보면 된다. 꼭지가 짧아 연습 전후로 한 편씩 읽기 좋다. 지망생에게 가장 쓸모 있는 것은 잘하는 법보다 오래 버티는 법에 관한 생각이라, 입시 결과와 상관없이 한 번 더 꺼내 읽게 된다. 저자는 샌포드 마이즈너의 말을 모토로 삼아 왔다고 밝히는데, 미국 연기 방법론의 갈래가 궁금해지면 같은 서재의 《아메리칸 액팅 메소드의 이해》로 넘어가 볼 수 있다.$q$,
  read_level = 1,
  for_whom = $q$공백기나 슬럼프를 지나는 사람, 연습이 막힌 연기 전공생$q$
where id = '53b8c1c7-0a29-4603-abee-08dc4a93e286';

-- 쓸 만한 인간
update public.syus_books set
  reader_reception = $q$배우 박정민이 2013년부터 잡지 《topclass》에 연재한 글을 모아 펴낸 첫 산문집이다. 독자들이 가장 많이 꼽는 점은 스스로를 찌질하다고 털어놓는 솔직함과, 자기를 낮추며 웃기는 유머다. 성공담을 늘어놓는 배우 에세이와 달리 불안과 서툶을 숨기지 않아, 가볍게 읽히다가 중반부터 공감이 깊어진다는 평이 많다. 개정증보판(2019)에는 저자가 직접 그린 그림과 손글씨가 더해졌고, 초판의 일부 표현이 고쳐졌다. 반대로 박정민을 좋아하는 사람이 아니라면 굳이 읽지 않아도 된다는 평도 있다 — 연기론을 기대하고 펴면 아쉬울 수 있다.$q$,
  reader_sources = $q$[{"name": "시사저널", "url": "https://www.sisajournal.com/news/articleView.html?idxno=190324"}, {"name": "소심한책방", "url": "https://sosimbook.com/product/%EC%93%B8-%EB%A7%8C%ED%95%9C-%EC%9D%B8%EA%B0%84/631/"}, {"name": "Goodreads", "url": "https://www.goodreads.com/book/show/51189716"}]$q$::jsonb,
  actor_guide = $q$연기 기술을 알려 주는 책이 아니다. 영화 《동주》(2016)로 이름이 알려지기 전부터 쓴 글이라, 한 배우가 불안한 시기의 일상과 가족, 여행을 어떤 마음으로 지나왔는지가 담겨 있다. 입시나 오디션에서 떨어진 직후, 연기를 계속해도 될지 흔들릴 때 읽기 좋다. 꼭지가 짧아 하루 한두 편씩 읽어도 된다. 다 읽은 뒤에는 같은 서재의 《배우의 방》이나 《신스틸러에게 묻다》로 다른 배우들의 이야기를 이어 읽어 보길 권한다.$q$,
  read_level = 1,
  for_whom = $q$연기를 계속할지 흔들리는 사람, 연기 책이 처음인 사람$q$
where id = '2395b726-9900-43eb-b1cd-50ca11a24ea1';

-- 생에 감사해
update public.syus_books set
  reader_reception = $q$배우 김혜자가 육십 년 연기 인생을 돌아본 에세이로, 2022년 말에 나온 뒤 꾸준히 읽히고 있다. 예스24에만 독자평이 백오십 건 넘게 쌓였고 대부분 호의적이다. 독자들은 자랑보다 서툶과 허무를 털어놓는 솔직함, 작품마다 마지막처럼 임해 온 태도, 그 시간을 지탱한 감사의 마음을 가장 많이 꼽는다. 한 꼭지를 읽고 나면 여운이 길어 잠시 쉬었다 읽게 된다는 평, 책을 계기로 옛 드라마를 다시 찾아본다는 평도 있다. 출판사에 따르면 2021~2022년의 구술과 인터뷰, 평생 써 온 일기 같은 글을 바탕으로 편집자가 초고를 만들고 저자가 기억과 사실을 보태 완성했다. 반대로 출연작 이야기가 많아 개인의 내면을 기대한 독자에게는 치우쳐 보였다는 평도 있다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개·독자평", "url": "https://www.yes24.com/product/goods/116046489"}, {"name": "알라딘 100자평", "url": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=306578793"}, {"name": "브라보마이라이프", "url": "https://bravo.etoday.co.kr/view/atc_view/14253"}]$q$::jsonb,
  actor_guide = $q$연기 기술서가 아니라, 한 배우가 평생 배역을 어떤 마음으로 맞아 왔는지를 적은 자전적 기록이다. 어떤 작품을 고르는지, 배역 앞에서 무엇을 거는지처럼 연기를 직업 이상으로 대해 온 시간이 담겨 있어, 배우라는 일을 몇 년이 아니라 수십 년 단위로 바라보게 해 준다. 376쪽으로 두꺼운 편이지만 스물네 꼭지로 나뉘어 있으니 한 꼭지씩 천천히 읽어도 된다. 책에 나오는 작품을 한두 편 찾아본 뒤 해당 꼭지를 다시 읽으면, 한 장면 뒤에 배우가 무엇을 쌓았는지가 더 잘 보인다. 입시를 앞두고 당장 쓸 무엇을 찾는다면 맞지 않고, 연기를 오래 하겠다는 마음을 다지고 싶을 때 펴는 책이다.$q$,
  read_level = 1,
  for_whom = $q$연기를 오래 하고 싶은 사람, 배우의 긴 시간이 궁금한 사람$q$
where id = '42d5d7d7-5464-4928-b23f-a21219f03969';

-- 즉흥연기 (Impro)
update public.syus_books set
  reader_reception = $q$1979년에 나온 뒤 즉흥극의 고전으로 꼽혀 온 책이다. 저자가 캐나다 캘거리에서 함께 세운 루스무스 극단이 퍼뜨린 시어터스포츠는 세계 곳곳의 즉흥 공연 형식으로 자랐고, 책은 열 개가 넘는 언어로 옮겨졌다. 영미권 서평은 출간 30년이 지나도 통찰이 낡지 않았다고 보고, 사람 사이의 높고 낮음이 말과 몸짓에서 어떻게 오가는지 다룬 지위 장과, 교사가 학생의 상상력을 어떻게 꺾는지 되짚는 대목을 연극 밖에서도 쓸모 있는 부분으로 꼽는다. 다만 로열코트 극장 시절 이야기처럼 시대가 느껴지는 부분이 있고, 제안을 받아들이거나 막는 원리 같은 내용은 이제 즉흥 수업의 기본이 되어 새롭지 않다는 지적도 있다. 국내판(지호, 2000) 독자평은 몇 건에 그치고, 평도 엇갈린다.$q$,
  reader_sources = $q$[{"name": "American Theatre(2023 추모 기사)", "url": "https://americantheatre.org/2023/04/25/the-man-who-tickled-the-great-intelligent-beast/"}, {"name": "Reviewsgate 서평", "url": "https://reviewsgate.co.uk/reviews-archive-part-2/impro-methuen-keith-jonstone"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/160380"}]$q$::jsonb,
  actor_guide = $q$대본 없이 무대에 서는 법을 다루지만, 결국 상대를 보고 반응하는 힘을 기르는 책이라 연기를 배우는 어느 단계에서 읽어도 좋다. 처음에는 지위 거래 놀이 장부터 읽고, 친구와 둘이 짧은 장면 하나를 서로의 높낮이를 바꿔 가며 해 보면 같은 대사가 얼마나 달라지는지 몸으로 알게 된다. 즉흥성과 이야기 만들기 장에는 머릿속 검열을 풀어 주는 연습이 많아, 실기에서 즉흥연기나 상황극을 보는 학교를 준비하거나 상대 앞에서 자꾸 굳는 사람에게 특히 맞다. 가면과 무아경 장은 지도자 없이 혼자 따라 하기보다 읽어 두는 데서 그치는 편이 안전하다. 장면 분석 중심의 《액팅 원》과 함께 읽으면, 계획하는 연기와 순간에 반응하는 연기 사이의 균형을 잡는 데 도움이 된다.$q$,
  read_level = 2,
  for_whom = $q$즉흥연기 실기를 준비하는 입시생, 상대 연기에서 자꾸 굳는 사람$q$
where id = 'cc3d0fb5-b16f-4bfb-966e-8e8fa3ca0061';

-- 질문하는 영화들
update public.syus_books set
  reader_reception = $q$한국일보 영화전문기자 라제기가 청소년 독자를 염두에 두고 쓴 책으로, 북트리거의 생각하는 10대 시리즈 가운데 한 권이다. 독자평은 많지 않고, 그 가운데 일부는 출간 직후 출판사에서 책을 받아 쓴 서평이다. 독자들은 《기생충》《어벤져스》처럼 많은 사람이 본 영화를 골라 줄거리부터 짚어 주니 영화를 보지 않았어도 따라갈 수 있다는 점, 아이와 함께 영화 이야기를 나누기 좋다는 점을 꼽는다. 정답을 건네기보다 스스로 질문하게 하는 방식을 좋게 본 평도 있다. 청소년 도서로 분류됐지만 어른이 읽어도 충분하다는 반응과 함께, 어른을 위한 판이 따로 있으면 좋겠다는 아쉬움이 나왔다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개·독자평", "url": "https://www.yes24.com/product/goods/78865776"}]$q$::jsonb,
  actor_guide = $q$연기 책이 아니라, 영화를 사회·역사·문화의 질문으로 읽는 연습을 시키는 책이다. 배우 지망생에게 쓸모는 작품을 보는 눈에 있다. 한 편의 영화가 무엇을 묻고 있는지 말할 수 있어야 그 안의 인물도 설명할 수 있기 때문이다. 연극영화과 면접에서 최근 인상 깊게 본 작품을 물을 때, 줄거리가 아니라 작품이 던지는 질문으로 답하는 연습에 알맞다. 다룬 스물다섯 편 가운데 본 영화의 장부터 읽고, 책의 해석에 동의하는지 아닌지를 자기 말로 한 줄씩 적어 보길 권한다. 2019년 기준의 최근작들이라, 지금 본 작품에도 같은 질문을 던져 보는 것까지가 이 책의 쓰임이다.$q$,
  read_level = 1,
  for_whom = $q$연극영화과 면접을 준비하는 고등학생, 작품 해석이 막막한 사람$q$
where id = 'b0dc8a1a-dde4-4d7c-b6c6-639720401b19';

-- 마이클 케인의 연기 수업 (Acting in Film)
update public.syus_books set
  reader_reception = $q$1980년대 말 BBC에서 방송한 영화 연기 특강을 1990년에 책으로 엮은 것으로, 영미권에서는 카메라 앞 연기를 처음 배우는 사람에게 자주 건네지는 실용서다. 독자들이 주로 꼽는 것은 이론 대신 촬영장에서 바로 쓰이는 요령과, 오랜 현장에서 겪은 일화를 풀어내는 저자의 입담이다. 준비를 철저히 하고 함께 일하는 사람을 존중하라는 직업인의 태도가 연기 요령보다 오래 남는다는 평도 있다. 반대로 분량이 얇아 책이라기보다 긴 소책자에 가깝다는 반응과, 너무 넓게 훑는다는 반응도 보인다. 국내판(바다출판사, 2017)은 서점 독자평이 열 건 남짓 쌓였고, 평가는 대체로 좋은 편이다.$q$,
  reader_sources = $q$[{"name": "Headbutler 서평", "url": "https://headbutler.com/reviews/michael-caine/"}, {"name": "Goodreads", "url": "https://www.goodreads.com/book/show/776196"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/40936847"}]$q$::jsonb,
  actor_guide = $q$무대 연기를 먼저 배운 사람이 카메라 앞에 처음 설 때 읽기 좋은 책이다. 아홉 장이 영화 연기란 무엇인가에서 시작해 준비하기, 촬영 현장, 촬영 전 카메라 앞, 촬영 실전, 캐릭터 창조, 배우로서의 몸가짐, 감독을 대하는 요령, 스타가 된다는 것으로 이어지니, 영상 수업 과제나 학생 단편 촬영 전에는 3~5장만 골라 읽어도 쓸모가 있다. 분량이 짧아 하루 이틀이면 다 읽힌다. 면접에서 매체 연기와 무대 연기의 차이를 묻는다면, 이 책에서 읽은 구체적인 요령 하나를 자기 촬영 경험과 이어 말하면 된다. 카메라 연기를 더 체계적으로 보고 싶다면 같은 서재의 《스크린 연기의 비밀》이나 《굿캐스팅》으로 이어 가길 권한다.$q$,
  read_level = 1,
  for_whom = $q$영상 연기를 처음 해 보는 무대 전공생, 학생 단편이나 오디션 촬영을 앞둔 사람$q$
where id = '108d2dc8-ebbe-4eef-a06c-f99eab0c4c77';

-- 음성연기를 위한 호흡·소리 훈련
update public.syus_books set
  reader_reception = $q$배우 이항나가 2005년에 낸 호흡·발성 훈련서로, 2020년에 개정판이 나왔다. 온라인 서점의 독자평은 거의 없다. 대신 대학 부설 교육기관의 화술 과목에서 김철홍의 《배우를 위한 화술과 연기》와 짝을 이뤄 부교재로 지정된 사례가 확인된다. 출판사 소개는 소리와 호흡 훈련을 따로 떼어 낸 기술이 아니라 연기 훈련의 연장으로 보는 관점을 이 책의 중심으로 꼽는다. 저자는 2021년 한국연기예술학회 학술지에 호흡 에쭈드(짜인 극적 상황 속에서 호흡으로 충동과 감정을 끌어내는 훈련)를 다룬 논문을 실어, 같은 문제의식을 연구로도 이어 갔다.$q$,
  reader_sources = $q$[{"name": "예스24(구판 책 소개)", "url": "https://www.yes24.com/product/goods/2105289"}, {"name": "국민대 미래인재교육원 화술Ⅱ 수업계획서", "url": "https://lifelong.kookmin.ac.kr/common/pdf/%ED%99%94%EC%88%A0%E2%85%A1.pdf"}, {"name": "연기예술연구 논문(아티클)", "url": "https://www.earticle.net/Article/A390493"}]$q$::jsonb,
  actor_guide = $q$소리가 목에 걸리거나 긴 대사에서 숨이 모자라는 사람이 먼저 펴 볼 만한 책이다. 긴장과 이완에서 시작해 호흡, 호흡 에쭈드, 소리를 거쳐 텍스트에 닿는 순서로 짜여 있으니, 소리 훈련부터 건너뛰지 말고 몸을 푸는 앞부분부터 차례로 따라가는 편이 좋다. 입시를 준비한다면 매일 짧게 할 수 있는 호흡 훈련 하나를 골라 독백 연습 전 준비 운동으로 붙여 두길 권한다. 면접에서 발성을 어떻게 훈련해 왔는지 물을 때, 이렇게 몸에 붙인 자기 루틴이 가장 설득력 있는 답이 된다. 말의 억양과 끊기 같은 우리말 규칙까지 다루고 싶다면 같은 서재의 《배우를 위한 화술과 연기》로 이어 가면 된다.$q$,
  read_level = 2,
  for_whom = $q$긴 대사에서 숨이 모자라는 사람, 발성 루틴을 세우고 싶은 연기 입시생$q$
where id = 'a32a03c4-bb9b-4aef-8020-edd88c68ea04';

-- 연출가를 위한 핸드북 (The Director's Craft)
update public.syus_books set
  reader_reception = $q$2009년 영국에서 나온 원서는 연출가가 리허설 전에 무엇을 준비하고 연습실에서 어떻게 일하는지를 단계별로 적은 실무서로 읽혀 왔다. 영국 국립극장이 낸 교육 자료는 이 책을 미첼의 대표 저작으로 소개하며, 이 책에서 정리된 사실주의 연기 체계가 영국의 연습실과 대학, 연극학교에서 널리 쓰인다고 설명한다. 국내판에는 손진책·김철리·김석만 등 연극인과 교수들이 추천의 말을 보탰다. 한계로 짚을 점은 방법 전체가 사실주의 연극을 전제로 짜여 있다는 것이다 — 저자 스스로도 책을 쓴 뒤 기법을 인물의 내력, 장소, 시간, 직전 상황, 사건, 의도의 여섯 층위로 줄여 다듬었다고 밝혔다. 국내 독자평은 많지 않다.$q$,
  reader_sources = $q$[{"name": "영국 국립극장 교육 자료(Practitioners in Practice)", "url": "https://images.nationaltheatre.org.uk/uploads/2024/03/KatieMitchell-PractitionersinPractice-PDF-2024.pdf"}, {"name": "예스24(책 소개·추천)", "url": "https://www.yes24.com/product/goods/92514259"}]$q$::jsonb,
  actor_guide = $q$연출 전공이 아니어도 연기과 학생에게 쓸모가 큰 책이다. 1부(리허설 준비)의 장면별 정보 구성하기, 희곡 속 행위 분석하기, 등장인물 작업 심화하기 장(2~5장)은 배우가 혼자 대본을 분석하는 순서로 그대로 옮겨 쓸 수 있다. 424쪽으로 두껍고 체호프의 《갈매기》를 줄곧 예로 들어 설명하므로, 《갈매기》를 먼저 읽어 두면 훨씬 수월하다. 처음부터 끝까지 읽기보다 2~5장을 먼저 읽고 입시 독백의 대본에 직접 적용해 보길 권한다. 연출 전공 면접을 준비한다면 같은 서재의 《연극연출: 원리와 기술》과 함께 읽으며 두 연출가가 연습 과정을 어떻게 나누는지 비교해 두면 좋다.$q$,
  read_level = 3,
  for_whom = $q$연출 전공 지망생, 대본 분석을 체계적으로 익히고 싶은 연기 전공생$q$
where id = 'f24223e4-9402-419c-9145-e63235981c03';

-- 연극연출: 원리와 기술
update public.syus_books set
  reader_reception = $q$1998년 집문당에서 나온 국내 연출 교재다. 독자 서평은 거의 없지만, 연출 기초 과목의 주교재로 오래 쓰여 온 기록이 남아 있다. 서울호서예술실용전문학교의 기초연출실습(2016·2017학년도)과 국민대 미래인재교육원의 연출의 이해 수업계획서가 이 책을 주교재로 적고 있고, 주차별 진도도 책의 다섯 부를 순서대로 따른다. 저자 안민수는 드라마센터 동랑 레퍼토리 극단에서 연출가로 일했고, 서울예술대학 학장과 한국연극학회 회장을 지냈다. 행동선(무대 위 동선)과 짓거리(동선에 얹히는 동작)처럼 연습실의 일을 우리말 용어로 풀어 쓴 점이 이 책의 결이다.$q$,
  reader_sources = $q$[{"name": "서울호서예술실용전문학교 기초연출실습 수업계획서", "url": "https://m.koreaart.ac.kr/info/dataroomDown.asp?idx=22109"}, {"name": "국민대 미래인재교육원 연출의 이해 수업계획서", "url": "https://lifelong.kookmin.ac.kr/common/pdf/%EC%97%B0%EC%B6%9C%EC%9D%98%EC%9D%B4%ED%95%B4.pdf"}, {"name": "예스24(목차·저자 소개)", "url": "https://www.yes24.com/product/goods/92705"}]$q$::jsonb,
  actor_guide = $q$연출 전공 입시를 준비하거나 연극과에서 첫 연출 실습을 앞둔 학생에게 맞는 책이다. 1부(예술로서의 연출)에서 연출의 역사와 훌륭한 연출가의 자질을 먼저 읽어 두면, 면접에서 연출가는 무엇을 하는 사람인가를 물을 때 자기 말로 답할 바탕이 생긴다. 3부의 희곡·인물 분석과 4부의 행동선, 리듬과 템포, 연습의 단계 장은 학과 공연이나 워크숍 작품을 직접 만들 때 단계별 점검표처럼 쓸 수 있다. 연기 전공생이라면 13장(배우의 연기 창조와 연출의 역할)부터 읽어도 연출가가 배우에게 무엇을 기대하는지 알 수 있다. 1998년에 나온 책이라 예로 든 무대 환경은 지금과 다른 대목이 있을 수 있으니, 같은 서재의 《연출가를 위한 핸드북》과 나란히 놓고 읽어 보길 권한다.$q$,
  read_level = 2,
  for_whom = $q$연출 전공 입시생, 첫 연출 실습을 앞둔 연극과 학생$q$
where id = 'cb10fab7-3aa1-4c66-bd52-8b1365de5eef';

-- 신스틸러에게 묻다
update public.syus_books set
  reader_reception = $q$매일경제 문화부 기자 김시균이 조연배우 스물다섯 명을 인터뷰해 엮은 책으로, 2019년에 나왔고 2023년에 큰글자책으로도 나왔다. 독자평은 많지 않지만, 주연 곁에서 극을 받쳐 온 배우들의 소박하고 진솔한 이야기가 편견을 깨 준다는 반응이 주를 이룬다. 독립영화와 작은 무대에서 일해 온 배우들까지 기록했다는 점, 가까이 앉아 이야기를 듣는 듯한 문답을 좋게 본 평이 있고, 꺼져 가던 열정을 다시 붙여 주었다는 한줄평도 있다. 오랜 무명과 생활의 어려움을 버텨 온 이야기에 마음이 간다는 독자가 많다. 반면 연기 자체를 깊이 묻는 질문이 적고, 오백 쪽에 가까운 분량에 비해 질문이 겉돈다는 서평단의 평도 있다.$q$,
  reader_sources = $q$[{"name": "예스24 책 소개·독자평", "url": "https://www.yes24.com/product/goods/75187785"}]$q$::jsonb,
  actor_guide = $q$연기 기술을 다루는 책이 아니라, 배우로 살아가는 시간을 듣는 인터뷰집이다. 진선규, 허성태, 이봉련, 남명렬, 김홍파 등 주연이 아닌 자리에서 오래 연기해 온 사람들의 이야기라, 스타가 되는 길보다 배우로 버티는 길을 먼저 보여 준다. 492쪽으로 길지만 스물다섯 편이 따로 읽히므로, 아는 배우의 장부터 골라 읽고 나머지는 천천히 넘어가도 된다. 입시나 오디션에서 연달아 떨어져 연기를 계속할지 고민될 때 특히 쓸모가 있다. 연기 자체를 깊이 묻는 대화를 원한다면 같은 서재의 《배우와 배우가》를 함께 읽는 편이 좋다.$q$,
  read_level = 1,
  for_whom = $q$오디션에서 연달아 떨어져 흔들리는 사람, 조연·단역부터 시작하는 배우$q$
where id = 'eafa9a73-f23e-4f70-b663-70fed939e43c';

-- 산연기 (Respect for Acting)
update public.syus_books set
  reader_reception = $q$1973년에 나온 뒤 미국 대학 연기 수업에서 교재로 널리 쓰여 온 책이다. 연극 평론가 해럴드 클러먼은 배우가 무대에서 부딪히는 문제를 쉽고 따뜻하게 짚었다고 평했고, 저자가 뉴욕 HB 스튜디오에서 오래 가르친 경험이 바탕이라는 점이 신뢰를 더한다. 가장 많이 논의되는 개념은 인물의 상황을 배우 자신의 삶에서 끌어온 감정과 상황으로 바꿔 놓는 대체로, 지금도 여러 연기 수업에서 가르친다. 흥미로운 점은 저자 자신이 훗날 이 책과 거리를 두었다는 것이다 — 1991년 《A Challenge for the Actor》를 새로 쓰면서 대체를 전이라는 말로 바꿨다. 국내에서는 1991년부터 같은 역자의 번역으로 이어져 왔지만, 서점 독자평은 많지 않다.$q$,
  reader_sources = $q$[{"name": "Wikipedia(Respect for Acting)", "url": "https://en.wikipedia.org/wiki/Respect_for_Acting"}, {"name": "Wikipedia(Uta Hagen)", "url": "https://en.wikipedia.org/wiki/Uta_Hagen"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/146833149"}]$q$::jsonb,
  actor_guide = $q$연기의 기초를 한 번 배운 뒤, 내 연기가 어딘가 꾸며진 것 같다고 느낄 때 읽기 좋은 책이다. 1부(배우 자신)에서 자기 감각과 기억을 재료로 쓰는 법을 읽고, 2부의 연습들을 하나씩 직접 해 보는 데 시간을 들이는 편이 낫다 — 읽기만 하면 절반만 남는 책이다. 3부(희곡과 역할)는 장면 분석을 배우는 2학년 무렵 다시 펴면 잘 들어온다. 입시 독백을 준비할 때 인물의 상황에 내 경험을 대어 보는 연습은 도움이 되지만, 아픈 기억을 억지로 끌어올리지는 말고 지도 선생과 함께 다루는 것이 좋다. 같은 서재의 《액팅 원》과 견주어 읽으면, 목표에서 출발하는 접근과 감각·경험에서 출발하는 접근이 어디서 만나는지 보인다.$q$,
  read_level = 2,
  for_whom = $q$기초를 배운 뒤 연기가 굳었다고 느끼는 사람, 연기 전공 1~2학년$q$
where id = '18b8cf17-7b1e-4f81-a370-c4876ca5377b';

-- 배우훈련 (Actor Training)
update public.syus_books set
  reader_reception = $q$영국 연출가이자 연극학자 앨리슨 호지가 엮은 책으로, 처음에는 《Twentieth Century Actor Training》이라는 제목으로 나왔고 2010년 실천가 여덟 명을 더한 2판이 《Actor Training》으로 나왔다. 국내판(동인, 2017)은 스타니슬랍스키부터 보알까지 열여덟 장으로, 2판을 옮긴 것이다. 각 장을 그 방법론을 오래 연구한 영미권 학자가 맡아, 영미권에서는 연극·공연학 공부에 널리 쓰이는 참고서로 소개된다. 공연 훈련을 다루는 영국 학술지는 다루는 폭이 넓으면서도 한 권으로서 일관성이 있다고 평했다. 여러 갈래를 한자리에서 견주어 볼 수 있다는 점이 자주 꼽히는 장점이며, 국내판 독자평은 거의 없다.$q$,
  reader_sources = $q$[{"name": "Routledge 책 소개", "url": "https://www.routledge.com/Actor-Training-2nd-Edition/Hodge/p/book/9780415471688"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/41221288"}]$q$::jsonb,
  actor_guide = $q$연기론을 한 권씩 다 읽기 전에 지도를 먼저 그려 보는 책이다. 연기론이나 연극사 수업을 듣는 2학년 이후 학생에게 맞고, 처음부터 끝까지 읽기보다 수업에서 다루는 사람의 장을 그때그때 찾아 읽는 사전처럼 쓰면 좋다. 각 장이 그 사람의 시대 배경과 훈련 원리, 대표 연습, 주요 공연을 함께 짚어, 연습 하나가 어떤 생각에서 나왔는지 알 수 있다. 입시 면접에서 좋아하는 연극인이나 연기론을 묻는다면, 이 책에서 한 사람을 골라 그 훈련을 직접 해 본 이야기로 답할 수 있다. 1장(스타니슬랍스키)은 《배우 수업》과, 9장(스트라스버그·애들러·마이즈너)은 《아메리칸 액팅 메소드의 이해》와, 11장(피터 브룩)은 《빈 공간》과 나란히 읽으면 좋다.$q$,
  read_level = 3,
  for_whom = $q$연기론·연극사 수업을 듣는 전공생, 여러 훈련법을 견주어 보고 싶은 사람$q$
where id = '0d4530ec-93ed-412a-92c5-9abc74ace774';

-- 아메리칸 액팅 메소드의 이해
update public.syus_books set
  reader_reception = $q$스타니슬랍스키 시스템이 미국으로 건너가 여러 갈래의 메소드로 나뉘고 서로 부딪쳐 온 과정을 다섯 장으로 정리한 국내 저작이다. 저자는 앞서 2008년에 스텔라 애들러의 인물 구축을 다룬 1권과, 리 스트라스버그·스텔라 애들러·샌포드 마이즈너의 이론을 견준 2권으로 이루어진 『아메리칸 액팅 메소드』를 냈고, 이 책은 그 6년 뒤에 나왔다. 온라인 서점에 남은 독자평은 찾지 못했다. 국내 연기 연구 논문에서 저자의 2008년 저작이 참고문헌으로 쓰이는 정도가 확인되는 반응이다. 훈련법을 따라 하게 하는 실기서가 아니라 연기론의 역사를 정리한 책이라는 점은 미리 알고 펴는 편이 좋다.$q$,
  reader_sources = $q$[{"name": "예스24(목차)", "url": "https://www.yes24.com/product/goods/14507534"}, {"name": "예스24(아메리칸 액팅 메소드 2)", "url": "https://www.yes24.com/product/goods/3494866"}, {"name": "KoreaScience(아메리칸 액팅 메소드 연구 논문)", "url": "https://koreascience.kr/article/JAKO202030155625403.page"}]$q$::jsonb,
  actor_guide = $q$메소드 연기라는 말을 들어 봤지만 스타니슬랍스키와 무엇이 다른지 헷갈리는 학생에게 지도가 되어 주는 책이다. 먼저 같은 서재의 《배우 수업》으로 스타니슬랍스키의 기본 개념을 잡은 뒤 이 책 1장(시스템과 메소드: 스타니슬랍스키의 미국화)을 읽으면 흐름이 잘 들어온다. 4장은 연극에서 영화로, 큰 연기에서 작은 연기로 옮겨 간 과정을 다루므로, 매체 연기를 지망한다면 이 장을 따로 챙겨 읽어도 좋다. 면접에서 영향을 받은 연기론을 묻는다면, 이 책으로 갈래의 차이를 정리해 두어야 이름만 늘어놓는 답을 피할 수 있다. 실제 훈련은 미국에서 오래 연기를 가르친 우타 하겐의 《산연기》나 이바나 처벅의 《배우의 힘》으로 이어 가 보길 권한다.$q$,
  read_level = 3,
  for_whom = $q$연기론의 계보를 정리하고 싶은 연극과 학생, 메소드 연기가 궁금한 매체 연기 지망생$q$
where id = 'e9903907-8b9b-4108-96ce-fe8117f0a229';

-- 굿캐스팅
update public.syus_books set
  reader_reception = $q$국립극단 연수단원 출신 연기 코치가 2014년에 낸 카메라 연기 입문서다. 예스24에 남은 독자 리뷰는 대부분 출간 직후에 쓰였고, 연기 과정을 단계별로 나눈 구성과 오디션 체크 항목, 촬영 스케줄표 같은 현장 정보가 실용적이라는 평이 많다. 그림과 용어 정리 덕분에 비전공자도 부담 없이 읽힌다는 반응, 책에 실린 배우들의 에세이가 촬영장을 간접 체험하게 해 준다는 반응도 이어진다. 아쉬운 쪽으로는 연기 노하우를 한 권에 다 담기는 어렵다는 지적이 있고, 출간 뒤 몇 해가 지난 최근의 독자평은 많지 않다.$q$,
  reader_sources = $q$[{"name": "예스24 독자 리뷰", "url": "https://www.yes24.com/product/goods/12554618"}]$q$::jsonb,
  actor_guide = $q$연극 위주로 연기를 배워 오다 매체 연기 입시나 첫 오디션을 앞둔 사람에게 맞는 책이다. 1부는 대본 분석에서 촬영까지 일곱 단계를 수업 대화 형식으로 따라가므로, 순서대로 읽으며 자기 독백 하나를 단계마다 다시 해 보는 식으로 쓰면 좋다. 2부의 오디션 체크포인트와 나쁜 연기 습관 점검은 오디션 전날의 점검표로, 촬영 스케줄표 읽기와 촬영장 구조 설명은 첫 단편영화 현장에 나가기 전에 읽어 두면 쓸모 있다. 2014년에 나온 책이라 오디션 방식과 현장 관행은 지금과 다른 부분이 있을 수 있다는 점은 감안하자. 카메라 앞 연기의 원리를 더 파고들고 싶다면 같은 서재의 《스크린 연기의 비밀》과 《마이클 케인의 연기 수업》으로 이어 가길 권한다.$q$,
  read_level = 1,
  for_whom = $q$매체 연기 입시를 앞둔 사람, 첫 오디션이나 촬영장을 앞둔 연기 입문자$q$
where id = 'ff54a70c-2a6d-44d0-bca7-58762735e564';

-- 스크린 연기의 비밀 (Secrets of Screen Acting)
update public.syus_books set
  reader_reception = $q$영국 연출가 패트릭 터커가 1990년대 초에 낸 책으로, 원서는 판을 거듭해 2023년 4판까지 나왔다. 메소드 계열이 아닌 접근을 내세워, 감정을 쌓는 법보다 샷의 크기와 프레임, 반응의 타이밍처럼 카메라가 실제로 무엇을 담는지에서 연기를 설명한다는 점이 특징으로 꼽힌다. 영미권에서도 독자평은 많지 않지만, 이 책을 바탕으로 화면 연기 수업을 꾸리는 연기 코치가 있을 만큼 실용서로 쓰인다. 4판에는 셀프테이프 오디션, 녹색 배경 앞 연기 같은 새 내용이 더해졌는데, 국내판(시공사, 1999)은 그보다 훨씬 앞선 판을 옮긴 것이라 촬영 환경과 업계 이야기는 지금과 다른 부분이 있을 수 있다. 국내판 독자평도 몇 건에 그친다.$q$,
  reader_sources = $q$[{"name": "Routledge 책 소개(4판)", "url": "https://www.routledge.com/Secrets-of-Screen-Acting/Tucker/p/book/9781032356969"}, {"name": "Acting Coach Scotland", "url": "https://actingcoachscotland.co.uk/blog/why-shot-sizes-shape-performance-close-up-to-long-shot"}, {"name": "예스24", "url": "https://www.yes24.com/product/goods/61707"}]$q$::jsonb,
  actor_guide = $q$무대 연기와 화면 연기가 어디서 갈라지는지를 원리로 정리해 주는 책이라, 매체 연기 수업을 앞둔 학생에게 맞다. 《마이클 케인의 연기 수업》이 현장 경험담이라면, 이 책은 같은 문제를 샷 크기와 프레임으로 풀어 주는 교과서에 가깝다. 휴대폰으로 같은 대사를 넓은 샷과 가까운 샷으로 찍어 보며 읽으면, 같은 연기가 화면에서 어떻게 커지고 작아지는지 바로 확인할 수 있다. 영상 연기 실기나 오디션 촬영을 준비할 때 프레임 안에서 움직임을 줄이고 시선을 다루는 감각을 익히는 데 쓸 만하다. 국내판이 오래된 판이라 촬영 현장 사정에 관한 대목은 시대를 감안해 읽고, 지금의 촬영장 이야기는 같은 서재의 《굿캐스팅》으로 보완하길 권한다.$q$,
  read_level = 2,
  for_whom = $q$매체 연기 수업을 앞둔 무대 전공생, 오디션 영상을 준비하는 사람$q$
where id = '9ed28d31-fcd3-4a8b-85fb-4adbcb8759cf';

-- 배우의 힘 (The Power of the Actor)
update public.syus_books set
  reader_reception = $q$할리우드 연기 코치 이바나 처벅이 2000년대 중반에 펴낸 책으로, 저자의 스튜디오는 스무 개 언어로 번역되었다고 밝힌다. 감정을 연기의 목적이 아니라 인물이 원하는 것을 얻기 위한 연료로 쓴다는 생각, 그리고 열두 단계로 정리된 작업 순서가 이 책의 중심이다. 영미권 독자평은 대체로 좋아, 장면을 준비할 때 무엇을 해야 할지 구체적으로 알려 주는 실용서라는 반응이 많다. 아쉬운 평으로는 단계가 정해져 있어 기계적으로 느껴진다는 의견, 같은 말이 되풀이되고 분량이 길다는 의견이 있다. 국내판(퍼스트북, 2023·증보판 2025)은 서점 독자평이 아직 거의 없다.$q$,
  reader_sources = $q$[{"name": "Ivana Chubbuck Studio", "url": "https://www.ivanachubbuck.com/about-studio/"}, {"name": "Goodreads", "url": "https://www.goodreads.com/book/show/611463"}, {"name": "알라딘", "url": "https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=373453517"}]$q$::jsonb,
  actor_guide = $q$장면마다 인물이 무엇을 원하고 무엇이 그것을 가로막는지를 단계별로 적어 가게 하는 책이라, 대본 분석을 손에 익히고 싶은 사람에게 맞다. 처음에는 전체 목표와 장면 목표, 장애물을 다루는 앞쪽 단계부터 자기 입시 독백에 하나씩 적용해 보고, 책에 실린 점검표로 빠진 것이 없는지 확인하면 된다. 대체나 내적 독백처럼 개인의 기억을 쓰는 단계는 강하게 작동하는 만큼, 혼자 아픈 기억을 깊이 파고들기보다 지도 선생과 함께 다루는 편이 안전하다. 감정을 짜내기보다 인물이 이기려고 애쓰는 쪽으로 연습하게 해, 오디션 장면에서 감정만 앞서다 굳는 사람에게 특히 도움이 된다. 같은 서재의 《산연기》와 견주어 읽으면, 대체라는 같은 도구를 두 선생이 어떻게 다르게 쓰는지 볼 수 있다.$q$,
  read_level = 2,
  for_whom = $q$대본 분석을 단계별로 익히고 싶은 사람, 오디션에서 감정만 앞서는 사람$q$
where id = '74bcc664-78c6-45c0-a030-3625b6b1fdb8';

-- 기존 「책 소개」 사실 정정 (기록팀 검수 11-11: 확인되지 않은 서술 교체)
update public.syus_books set intro = $q$한국어 발음·호흡의 특성에 맞춰 정리한 국내 저자의 화술 훈련서. 소리마루·억양·호흡과 끊기·템포·휴지·장단음·자음과 모음 같은 항목을 무대 위 발화와 연결해 설명한다는 점에서, 번역서 위주의 서가에 드문 국내 실기서다.$q$ where id = '697d17ad-b06a-4877-bde0-bb71d1ca716b';  -- 배우를 위한 화술과 연기

update public.syus_books set intro = $q$스타니슬랍스키 시스템이 미국으로 건너가 여러 갈래의 메소드로 나뉘고 부딪치며 자라 온 과정을 정리한 책. 연기 집단의 분화와 대립, 연극에서 영화로의 이동까지를 따라간다. 국내 저자가 쓴 연구서다.$q$ where id = 'e9903907-8b9b-4108-96ce-fe8117f0a229';  -- 아메리칸 액팅 메소드의 이해

commit;

-- 확인: 24가 나와야 한다
select count(*) as filled from public.syus_books where reader_reception is not null and actor_guide is not null;
